/* FitIn interaction prototype. Recommendation rules here are explicit examples, not a validated training prescription. */
'use strict';
const $ = s => document.querySelector(s);
const machines = {
 shoulderPress:{name:'덤벨 숄더 프레스',part:'어깨 · 삼두',pattern:'수직 밀기',shape:'양손 덤벨 · 등받이 벤치',setup:'가벼운 덤벨을 어깨 높이에서 잡고, 손목과 팔꿈치를 정렬해요.',cue:'허리를 과하게 젖히지 않고 천천히 위로 밀어주세요.',steps:['발을 바닥에 붙이고 편안한 무게를 고르세요.','팔꿈치 아래에 손목을 두고 덤벨을 위로 밀어요.','통제할 수 있는 범위에서 천천히 돌아오세요.']},
 legPress:{name:'레그 프레스',part:'허벅지 · 엉덩이',pattern:'무릎 중심 하체',shape:'큰 발판 · 기울어진 좌석',setup:'등과 엉덩이를 패드에 붙이고 발을 어깨너비로 놓아요.',cue:'무릎을 발끝 방향으로 움직이고 끝에서 잠그지 마세요.',steps:['큰 발판과 기울어진 좌석을 찾아요.','가동 범위와 안전장치 위치를 직원에게 확인해요.','등과 엉덩이를 붙인 채 발판을 천천히 밀어요.']},
 chestPress:{name:'체스트 프레스',part:'가슴 · 삼두',pattern:'수평 밀기',shape:'등받이 · 가슴 높이 손잡이',setup:'손잡이가 가슴 중앙 높이에 오도록 의자를 맞춰요.',cue:'어깨를 내리고, 손목을 꺾지 않은 채 손잡이를 밀어요.',steps:['등받이 양옆에 앞으로 미는 손잡이가 있어요.','가슴 중앙에 손잡이가 오도록 좌석을 조절해요.','등을 붙이고 천천히 밀었다 돌아와요.']},
 latPulldown:{name:'랫 풀다운',part:'등 · 이두',pattern:'수직 당기기',shape:'머리 위 긴 바 · 허벅지 패드',setup:'허벅지 패드를 고정하고 발을 바닥에 붙여요.',cue:'반동을 줄이고 바를 가슴 위쪽으로 당겨주세요.',steps:['높이 달린 긴 바와 좌석 앞 패드를 찾아요.','허벅지가 들리지 않도록 패드를 고정해요.','어깨를 내린 채 팔꿈치를 아래로 당겨요.']},
 legCurl:{name:'시티드 레그 컬',part:'허벅지 뒤',pattern:'무릎 굽히기',shape:'좌석 · 허벅지와 발목 패드',setup:'기구 회전축을 무릎에 맞추고 패드를 고정해요.',cue:'허리를 붙이고 무릎을 천천히 구부려주세요.',steps:['다리를 아래로 굽히는 패드형 기구예요.','회전축과 무릎이 맞는지 직원에게 확인해요.','상체를 고정하고 천천히 구부렸다 돌아와요.']},
 row:{name:'시티드 로우',part:'등 · 이두',pattern:'수평 당기기',shape:'가슴 패드 · 앞쪽 당기는 손잡이',setup:'가슴 패드와 좌석을 맞추고 손목을 곧게 유지해요.',cue:'어깨를 내리고 팔꿈치를 뒤로 보내세요.',steps:['앞쪽 손잡이를 몸으로 당기는 기구예요.','발을 고정하고 가슴 패드 높이를 맞춰요.','몸을 젖히지 않고 손잡이를 몸쪽으로 당겨요.']},
 legExtension:{name:'레그 익스텐션',part:'허벅지 앞',pattern:'무릎 펴기',shape:'좌석 · 정강이 앞 패드',setup:'패드를 발목 바로 위에 놓고 회전축을 무릎에 맞춰요.',cue:'천천히 무릎을 펴고 과하게 잠그지 마세요.',steps:['정강이 앞 패드를 위로 드는 기구예요.','좌석과 패드를 조절해 무릎 축을 맞춰요.','상체를 고정하고 천천히 다리를 펴요.']},
 pecDeck:{name:'펙 덱',part:'가슴',pattern:'가슴 모으기',shape:'높은 등받이 · 양옆 팔 패드',setup:'팔꿈치와 어깨 높이를 편하게 맞춰요.',cue:'어깨가 뒤로 과하게 꺾이지 않는 범위에서 모아주세요.',steps:['양옆 팔 패드를 앞으로 모으는 기구예요.','시작 각도와 좌석 높이를 직원에게 확인해요.','가슴 앞쪽으로 천천히 모았다 돌아와요.']},
 reverseGrip:{name:'덤벨 리버스 그립 로우',part:'등 · 이두',pattern:'수평 당기기',shape:'양손 덤벨 · 상체를 숙여 당기기',setup:'손바닥이 앞을 향하게 덤벨을 잡고, 엉덩이를 뒤로 보내 상체를 숙여요.',cue:'허리의 중립을 유지하고 반동 없이 팔꿈치를 뒤로 당겨주세요.',steps:['가벼운 덤벨을 역그립으로 잡아요.','무릎을 약간 굽히고 엉덩이를 뒤로 보내요.','몸통을 고정하고 덤벨을 옆구리 쪽으로 당겨요.']},
};
const plans={full:['legPress','chestPress','latPulldown','legCurl','row'],upper:['chestPress','row','latPulldown','pecDeck'],lower:['legPress','legCurl','legExtension'],push:['shoulderPress','chestPress','pecDeck'],pull:['latPulldown','row'],same:['legPress','chestPress','latPulldown','legCurl','row']};
const splitNames={full:'전신',upper:'상체',lower:'하체',push:'밀기',pull:'당기기',same:'고정 전신'};
const defaults={level:'beginner',split:'full',feeling:'good',sound:true,starter:false,history:[],session:null,items:plans.full.map(id=>({id,sets:3,rest:90}))};
let state=structuredClone(defaults), page='today', logs=[], ctx, demoTimer, toastTimer, saveError=false;
const key='fitin.prototype.v1';
const validItems=items=>Array.isArray(items)&&items.length>0&&items.length<=8&&new Set(items.map(x=>x.id)).size===items.length&&items.every(x=>machines[x.id]&&Number.isInteger(x.sets)&&x.sets>=1&&x.sets<=5&&Number.isInteger(x.rest)&&x.rest>=30&&x.rest<=180);
try{const raw=localStorage.getItem(key);if(raw){const d=JSON.parse(raw);if(d.version!==1||!validItems(d.items)||!Array.isArray(d.history)||!['beginner','intermediate','advanced'].includes(d.level)||!plans[d.split]||!['good','tired','pain'].includes(d.feeling)||typeof d.sound!=='boolean'||typeof d.starter!=='boolean')throw Error('schema');state={...defaults,...d};if(state.session){const s=state.session;if(!Array.isArray(s.phases)||!s.phases.length||!s.phases.every(p=>Number.isFinite(p.seconds)&&p.seconds>=0&&['warmup','move','work','rest','cooldown'].includes(p.kind)&&(!p.id||machines[p.id]))||!Number.isFinite(s.elapsed)||!Number.isFinite(s.anchor)||typeof s.paused!=='boolean'||!Array.isArray(s.confirmed))throw Error('session');}}}catch{saveError=true;state=structuredClone(defaults);}
function persist(){if(saveError)return;try{localStorage.setItem(key,JSON.stringify({...state,version:1}));}catch{saveError=true;toast('저장 공간에 접근하지 못했어요. 현재 화면은 유지되지만 새로고침 시 기록이 사라질 수 있어요.');}}
function toast(text){clearTimeout(toastTimer);$('#toast').textContent=text;$('#toast').hidden=false;toastTimer=setTimeout(()=>$('#toast').hidden=true,5000);}
function fmt(s){s=Math.max(0,Math.ceil(s));return `${String(Math.floor(s/60)).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`;}
function budget(items=state.items){const work=items.reduce((s,x)=>s+x.sets*60,0),rest=items.reduce((s,x)=>s+(x.sets-1)*x.rest,0),move=items.length*60;return {work,rest,move,base:180+work+rest+move+120,total:Math.max(2400,180+work+rest+move+120),cool:Math.max(120,2400-180-work-rest-move)};}
function setItems(){state.items=plans[state.split].map(id=>({id,sets:state.feeling==='tired'?2:3,rest:90}));if(state.starter&&['full','same','upper'].includes(state.split)){const rest=state.items.filter(x=>!['chestPress','row','shoulderPress','reverseGrip'].includes(x.id));state.items=[{id:'shoulderPress',sets:3,rest:90},{id:'reverseGrip',sets:3,rest:90},...rest];}persist();render();}
function reason(){if(state.feeling==='pain')return '통증이 있다면 운동을 시작하지 않아요. 회복 후 다시 체크인해주세요.';if(state.feeling==='tired')return '오늘은 피로를 고려해 세트를 줄였어요. 남는 시간은 가벼운 회복 구간으로 바꿔요.';const last=state.history.at(-1);if(last&&Date.now()-last.at<86400000)return '같은 날 기록이 있어요. 같은 부위를 연속으로 강하게 운동하기보다 회복을 먼저 확인해주세요.';return state.starter&&state.items.some(x=>x.id==='shoulderPress')?'선택한 시작 운동을 포함해 40분으로 재구성했어요. 체스트 프레스·시티드 로우를 대체한 예시이며, 기본 추천은 머신 중심입니다.':'최근 기록과 선호 분할을 확인하는 추천 예시예요. 실제 추천 엔진은 서비스 설계에서 확인하세요.';}
function levelLabel(){return {beginner:'초보자',intermediate:'중수',advanced:'고급'}[state.level];}
function heading(over,title,sub){return `<section class="heading"><div><div class="eyebrow">${over}</div><h1>${title}</h1><p>${sub}</p></div><div class="date">${new Date().toLocaleDateString('ko-KR',{month:'long',day:'numeric',weekday:'long'})}</div></section>`;}
function render(){document.querySelectorAll('[data-page]').forEach(b=>{b.classList.toggle('active',b.dataset.page===page);b.setAttribute('aria-current',b.dataset.page===page?'page':'false');});$('#page-label').textContent={today:state.session?'진행 중인 운동':'오늘의 운동',library:'기구 가이드',history:'나의 기록',plan:'서비스 설계'}[page];$('#view').innerHTML=page==='today'?(state.session?liveView():todayView()):page==='library'?libraryView():page==='history'?historyView():planView();bind();if(state.session&&page==='today')updateLive();}
function todayView(){const b=budget();return heading('A LITTLE LESS THINKING. A LITTLE MORE YOU.','오늘은, 그냥 오세요.','운동 순서부터 마지막 휴식까지. 나에게 집중하는 40분.')+`<div class="layout"><section class="main-column"><div class="hero"><div class="hero-copy"><div class="hero-kicker">오늘의 추천 <span class="badge">${levelLabel()}</span></div><h2>${state.starter&&state.items[0]?.id==='shoulderPress'?'내 운동을 더한':'머신으로 채우는'}<br>${splitNames[state.split]} 루틴</h2><div class="stats"><div><strong>40<small> 분</small></strong><p>휴식과 이동까지</p></div><span class="divider"></span><div><strong>${state.items.length}<small> 운동</small></strong><p>하나씩, 차근차근</p></div></div></div><div class="hero-art"><img src="assets/${state.items[0].id}.svg" alt="${machines[state.items[0].id].name} 형태 그림"></div></div><div class="reason"><span class="reason-icon">↻</span><p>${reason()}</p></div><div class="section-head"><h2>오늘의 순서</h2><button class="text-button" id="customize">내 루틴으로 수정 ↗</button></div><div class="machine-list"><div class="bookend"><small>WARM UP</small><span>걷기 · 가벼운 몸 풀기</span><span>3분</span></div>${state.items.map((x,i)=>`<div class="machine-row"><span class="index">${String(i+1).padStart(2,'0')}</span><img class="thumb" src="assets/${x.id}.svg" alt="${machines[x.id].shape}"><div class="row-info"><button data-detail="${x.id}">${machines[x.id].name} ↗</button><p>${machines[x.id].part} · ${x.sets}세트 · 휴식 ${x.rest}초</p></div><div class="row-actions"><button class="icon-button" data-up="${i}" aria-label="${machines[x.id].name} 위로" ${i===0?'disabled':''}>↑</button><button class="icon-button" data-down="${i}" aria-label="${machines[x.id].name} 아래로" ${i===state.items.length-1?'disabled':''}>↓</button></div></div>`).join('')}<div class="bookend"><small>COOL DOWN</small><span>정리 · 호흡 · 가벼운 회복</span><span>${fmt(b.cool)}</span></div></div><p class="mini-note">기구를 누르면 생김새와 사용법이 나와요. 붐비면 순서를 바꿔보세요.</p></section><aside class="aside"><div class="card"><h3>오늘의 나에게 맞추기</h3><div class="segmented" aria-label="난이도">${['beginner','intermediate','advanced'].map((v,i)=>`<button data-level="${v}" class="${state.level===v?'selected':''}" aria-pressed="${state.level===v}">${['초보자','중수','고급'][i]}</button>`).join('')}</div><p class="mini-note" id="level-note">${state.level==='beginner'?'자세와 기구 적응이 먼저. 여유 있는 무게로 시작해요.':state.level==='intermediate'?'반복 수와 무게를 기록하며 점진적으로 조절해요.':'수행 기록과 목표에 따라 운동량을 직접 조절해요.'}</p><label class="field" for="split">운동 방식</label><select class="select" id="split">${Object.entries(splitNames).map(([v,n])=>`<option value="${v}" ${state.split===v?'selected':''}>${n}${v==='full'?' · 불규칙한 방문에 추천':''}</option>`).join('')}</select><label class="field" style="display:flex;align-items:center;gap:8px"><input type="checkbox" id="starter" ${state.starter?'checked':''}>나만의 시작 운동 사용 · 선택 기능</label><p class="mini-note">시연: 덤벨 2개로 기존 운동 2개를 대체해 40분을 유지해요. 출시 버전은 시작 운동을 직접 선택합니다.</p><label class="field">오늘 몸 상태는 어때요?</label><div class="checkin-grid">${[['good','괜찮아요'],['tired','피곤해요'],['pain','통증 있어요']].map(([v,n])=>`<button data-feeling="${v}" class="${state.feeling===v?'selected':''}" aria-pressed="${state.feeling===v}">${n}</button>`).join('')}</div><hr class="rule"><div class="budget-top"><span class="caption">오늘의 시간 예산</span><strong>${Math.ceil(b.total/60)}<small> / 40분</small></strong></div><div class="budget-bars"><i style="width:${b.work/b.total*100}%;background:#4c7253"></i><i style="width:${b.rest/b.total*100}%;background:#a8bb89"></i><i style="width:${b.move/b.total*100}%;background:#d5ba91"></i><i style="flex:1;background:#e4e9d8"></i></div><div class="legend"><span><i style="background:#4c7253"></i>운동</span><span><i style="background:#a8bb89"></i>휴식</span><span><i style="background:#d5ba91"></i>이동</span><span><i style="background:#e4e9d8"></i>준비·회복</span></div>${b.base>2400?'<p class="mini-note" style="color:#b16845">40분을 넘었어요. 세트나 기구 수를 조절해주세요.</p>':''}<div style="margin-top:22px"><button class="primary" id="start" ${b.base>2400||state.feeling==='pain'?'disabled':''}>체크인하고 40분 시작 &nbsp; →</button></div><p class="start-note">일시정지를 누르면 모든 시간이 멈춰요.<br>자동 진행은 실제 수행 완료와 별도로 기록해요.</p></div><div class="card audio-card"><div class="audio-header"><h3>음악 사이로, 코치의 한마디</h3><input class="switch" type="checkbox" id="sound" aria-label="음성 및 비프 안내" ${state.sound?'checked':''}></div><p>“운동을 시작하겠습니다.”<br>세트 종료 5초 전부터 비프 5번.</p><div class="audio-buttons"><button id="voice-test">▷ 음성 듣기</button><button id="beep-test">♪ 5초 비프 듣기</button></div><p class="mini-note">웹은 브라우저 음성으로 시연해요.<br>다른 음악 앱 덕킹은 iPhone에서 검증해요.</p></div></aside></div>`;}
function libraryView(){return heading('KNOW YOUR NEXT MOVE.','처음 보는 기구도, 익숙하게.','생김새를 찾고, 짧은 동작을 보고, 한 가지 자세에 집중해요.')+`<div class="grid-cards">${Object.entries(machines).map(([id,m])=>`<button class="library-card" data-detail="${id}"><img src="assets/${id}.svg" alt="${m.shape}"><h3>${m.name}</h3><p>${m.shape}</p><span>${m.part} &nbsp; · &nbsp; ${['shoulderPress','reverseGrip'].includes(id)?'동작 시연 보기 →':id==='reverseGrip'?'동작 시연 보기 →':'사용법 보기 →'}</span></button>`).join('')}</div><p class="mini-note">그림은 기구 형태를 구분하기 위한 도식입니다. 실제 모델마다 구조가 달라요. 출시용 콘텐츠에는 검수한 동작 영상과 기구별 사진을 연결합니다.</p>`;}
function historyView(){return heading('EVERY VISIT COUNTS.','꾸준함은, 기록이 되니까.','프로토타입에서 직접 진행한 기록만 표시해요. 실제 운동 기록과 분리됩니다.')+(state.history.length?state.history.slice().reverse().map(r=>`<div class="record"><div><h3>${splitNames[r.split]||'나의'} 루틴 · ${r.complete?'시간 완료':'중간 종료'}</h3><p>${new Date(r.at).toLocaleString('ko-KR')} · 직접 완료 ${Number(r.confirmed)||0}세트<br>체감 난이도: ${r.effort==='easy'?'여유로웠어요':r.effort==='hard'?'버거웠어요':'기록 안 함'} · 다음 추천에 활용할 입력</p></div><strong>${fmt(Number(r.elapsed)||0)}</strong></div>`).join(''):`<div class="empty"><div style="font-size:37px;color:#a4b288">↗</div><h2>첫 체크인을 기다리고 있어요.</h2><p>매일 오지 않아도 괜찮아요.<br>다음에 올 때, 여기서 이어가면 되니까요.</p><button class="primary" data-page="today">오늘의 운동 살펴보기 →</button></div>`);}
function planView(){return heading('THE THINKING BEHIND YOUR 40 MINUTES.','믿고 맡기고, 내 방식으로 바꾸고.','현재 화면은 동작을 검토하기 위한 기획 프로토타입입니다. 추천 엔진과 네이티브 기능은 개발 예정입니다.')+`<div class="plan-banner"><h2>결정을 줄여주는 코치. 선택권은 언제나 나에게.</h2><p>‘스파르타’는 자동으로 흐름을 이어주는 방식입니다. 무게·휴식·중단을 강요하지 않습니다.</p></div><div class="plan-grid"><article class="plan-card"><span class="num">01 / ROUTINE ENGINE</span><h2>요일보다 최근 실제 수행</h2><div class="flow"><span>체크인</span><span>최근 부위·수행량</span><span>피로·통증</span><span>다음 루틴</span></div><p>전신 / 상·하체 / 밀기·당기기·하체 / 고정 루틴을 각각 지원합니다. 세션 날짜만 보지 않고 부위별 실제 수행과 간접 자극까지 계산합니다.</p><ul><li>기본안: 불규칙하게 오는 초보는 전신 중심.</li><li>어깨 프레스 후 가슴 운동은 삼두·어깨의 중복 부담도 고려.</li><li>같은 부위를 연속일에 강하게 훈련하는 고정 루틴은 회복 대안을 함께 표시.</li><li>오랜 공백 뒤에는 빠진 운동 몰아넣기 대신 적응 세션 제안.</li></ul></article><article class="plan-card"><span class="num">02 / YOUR ROUTINE</span><h2>선호는 유지하고, 수정은 쉽게</h2><p>기본 추천은 머신 중심입니다. ‘나만의 시작 운동’에서 선택한 운동·세트·순서를 저장하고, 전체 40분 안에서 나머지 운동을 재구성합니다. 덤벨은 선택 가능한 운동의 한 예일 뿐입니다.</p><ul><li>기구별 이름·형태·짧은 동작·주요 자극 부위.</li><li>‘기구 사용 중’ → 같은 동작 패턴의 대체 기구 제안.</li><li>순서·세트·휴식·반복 수·중량을 개인화.</li><li>수정 시 예상 시간, 직접·간접 부위 편중 표시.</li><li>40분 초과 시 기구·세트를 조절. 휴식은 몰래 줄이지 않음.</li></ul></article><article class="plan-card"><span class="num">03 / HANDS-FREE COACH</span><h2>귀로 듣고, 운동에 집중</h2><ol><li>“운동을 시작하겠습니다. 가볍게 몸을 풀어주세요.”</li><li>“덤벨 숄더 프레스, 첫 번째 세트입니다.”</li><li>종료 5·4·3·2·1초에 짧은 비프. 종료 시 다른 톤.</li><li>“세트가 끝났습니다. 90초 동안 쉬세요.”</li><li>“사용한 기구를 정리하고, 다음 기구로 이동하세요.”</li></ol><p>OS 오디오 세션으로 음악 덕킹·복귀. 잠금화면 알림과 이어폰 연결 해제 시 동작은 실기기 하네스로 검증합니다. 웹 TTS는 언어·기기에 따라 음색이 달라요.</p></article><article class="plan-card"><span class="num">04 / PROGRESSION</span><h2>난이도와 분할은 별개</h2><p>초보: 기구 설정과 자세 적응.<br>중수: 중량·반복 수·체감 여유 기록.<br>고급: 목표별 운동량·분할 조정.</p><p style="margin-top:12px">방문 횟수만으로 자동 승급하지 않습니다. 실제 수행 안정성, 통증 여부, 사용자의 선택을 확인합니다. 자동 경과한 세트를 완료한 것으로 간주하지 않습니다.</p></article><article class="plan-card"><span class="num">05 / BUILD & HARNESS</span><h2>먼저 웹, 다음 iPhone, 그다음 Watch</h2><ul><li>웹: 화면·시간 엔진·순서 변경·저장·음성·비프 시연.</li><li>공통 코어: React Native + TypeScript, 오프라인 영구 저장.</li><li>iPhone: 오디오 덕킹·백그라운드 알림·중단/복구 검증.</li><li>Watch: SwiftUI 동반 앱, WatchConnectivity, 단일 세션 권한·명령 중복 방지.</li><li>Android: 동일 코어 + 오디오 포커스·알림 검증.</li></ul><p>Git + 자동 테스트 + 가상시계 + 브라우저 시나리오 + 실제 기기 체크리스트를 함께 관리합니다. 회원가입·백엔드 없이 시작합니다.</p></article><article class="plan-card"><span class="num">06 / EVIDENCE & CONTENT</span><h2>추천 근거와 콘텐츠 검수</h2><p>주요 근육군의 규칙적인 훈련과 점진적 적응을 기본으로 삼고, 같은 부위의 회복을 고려합니다. 40분·종목 순서·초기 세트 수는 제품 설계안이며 모든 사람에게 최적인 처방은 아닙니다.</p><p style="margin-top:12px"><a href="https://acsm.org/resistance-training-guidelines-update-2026/" target="_blank" rel="noopener">ACSM 2026 저항운동 가이드라인</a><br><a href="https://www.mayoclinic.org/healthy-lifestyle/fitness/basics/strength-training/hlv-20049447" target="_blank" rel="noopener">Mayo Clinic · 동일 근육군의 휴식</a><br><a href="https://www.youtube.com/shorts/gid8N53_Tq0" target="_blank" rel="noopener">사용자 참고 쇼츠 · 덤벨 동작 표현 방식</a></p><p style="margin-top:12px">영상은 권리 확보·자세 검수 후 오프라인에 포함합니다. 참고 영상을 복제하지 않습니다. 회복 추정치는 진단으로 표시하지 않습니다.</p></article></div>`;}
function modal(title,html){$('#modal-title').textContent=title;$('#modal-content').innerHTML=html;$('#modal').showModal();}
function showDetail(id){const m=machines[id];modal(m.name,`<div class="machine-detail"><div><img src="assets/${id}.svg" alt="${m.shape}"><p class="mini-note">기구·동작 형태 도식 · 실제 모델은 다를 수 있어요.</p>${['shoulderPress','reverseGrip'].includes(id)?'<button class="primary" id="motion" style="margin-top:15px">▷ 짧은 동작 시연 보기</button>':''}</div><div><span class="detail-tag">${m.part} · ${m.pattern}</span><h3>이렇게 생겼어요</h3><p>${m.shape}</p><h3>시작 전, 세 가지만</h3>${m.steps.map((s,i)=>`<div class="step"><b>${i+1}</b><p>${s}</p></div>`).join('')}<div class="alert" style="margin-top:18px">${m.cue}<br>첫 기구 설정은 직원에게 확인하세요. 통증이 있으면 멈추세요.</div></div></div>`);$('#motion')?.addEventListener('click',()=>showMotion(id));}
function showMotion(id){const reverse=id==='reverseGrip';$('#modal-title').textContent=machines[id].name+' · 동작 미리보기';$('#modal-content').innerHTML=`<div style="max-width:360px;margin:auto;text-align:center"><div style="background:#eaf0e0;border-radius:17px;padding:20px"><span class="detail-tag">${machines[id].part} · 자극 부위 강조</span><img id="motion-img" src="assets/${id}.svg" style="width:100%" alt="${machines[id].name} 시작 자세"><div id="motion-caption" style="font-size:16px;font-weight:700;margin-top:12px">01 · 시작 자세</div><div class="progress" style="background:#d5dec6"><i id="motion-progress" style="width:0;background:#a7bd7b"></i></div></div><p class="mini-note">시작·수축 자세를 번갈아 보여주는 기획 시연입니다.<br>출시 버전은 검수한 짧은 반복 영상으로 대체합니다.</p><button class="secondary" id="motion-toggle" style="margin-top:15px">Ⅱ 시연 멈추기</button><p style="font-size:12px;margin-top:15px">${machines[id].cue}</p><a href="https://www.youtube.com/shorts/gid8N53_Tq0" target="_blank" rel="noopener" class="text-button" style="display:inline-block;margin-top:12px">참고 쇼츠 열기 ↗</a></div>`;let pose=0,playing=true;clearInterval(demoTimer);demoTimer=setInterval(()=>{if(!playing||!$('#motion-img'))return;pose=1-pose;$('#motion-img').src=`assets/${id}${pose?'-end':''}.svg`;$('#motion-caption').textContent=pose?(reverse?'02 · 팔꿈치를 뒤로 당기기':'02 · 천천히 위로 밀기'):'01 · 시작 자세';$('#motion-progress').style.width=pose?'100%':'0';},1500);$('#motion-toggle').onclick=()=>{playing=!playing;$('#motion-toggle').textContent=playing?'Ⅱ 시연 멈추기':'▷ 시연 다시 보기';};}
function customize(){modal('내 루틴으로 수정',`<p class="mini-note" style="margin:0 0 16px">기구·세트·휴식을 바꾸면 총시간을 다시 계산해요. 1세트 운동 구간은 60초입니다.</p><div class="edit-row edit-head"><span>운동 / 대체 종목</span><span>세트</span><span>휴식(초)</span></div>${state.items.map((x,i)=>`<div class="edit-row"><select class="select" data-edit-id="${i}" aria-label="${i+1}번째 운동">${Object.entries(machines).filter(([id])=>id!=='pecDeck'||state.split!=='lower').map(([id,m])=>`<option value="${id}" ${id===x.id?'selected':''}>${m.name}</option>`).join('')}</select><input type="number" min="1" max="5" value="${x.sets}" data-edit-sets="${i}" aria-label="${i+1}번째 운동 세트"><input type="number" min="30" max="180" step="15" value="${x.rest}" data-edit-rest="${i}" aria-label="${i+1}번째 운동 휴식"></div>`).join('')}<div id="edit-budget" class="edit-total"></div><div id="edit-warning" class="alert" hidden></div><button class="primary" id="apply-edit">이 루틴으로 적용</button>`);const read=()=>state.items.map((_,i)=>({id:$(`[data-edit-id="${i}"]`).value,sets:Number($(`[data-edit-sets="${i}"]`).value),rest:Number($(`[data-edit-rest="${i}"]`).value)}));const update=()=>{const items=read(),valid=validItems(items),b=budget(items);$('#edit-budget').textContent=valid?`운동·휴식·이동 ${fmt(b.base-300)} + 준비 3분 + 회복 ${fmt(b.cool)} → 전체 ${fmt(b.total)}`:'각 운동은 중복 없이, 세트 1–5개, 휴식 30–180초로 입력해주세요.';$('#apply-edit').disabled=!valid||b.base>2400;const warning=[];if(b.base>2400)warning.push('40분을 넘어요. 세트나 기구 구성을 줄여주세요. 휴식을 자동으로 줄이지 않아요.');const patterns=items.map(x=>machines[x.id].pattern);if(!patterns.some(p=>p.includes('당기기')))warning.push('당기기 운동이 없어요. 분할 의도에 맞는지 확인해주세요.');if(new Set(patterns).size<3)warning.push('비슷한 동작에 편중돼 있어요. 목표 분할과 주간 회복을 확인해주세요.');$('#edit-warning').hidden=!warning.length;$('#edit-warning').textContent=warning.join(' ');};document.querySelectorAll('.edit-row input,.edit-row select').forEach(x=>x.oninput=update);$('#apply-edit').onclick=()=>{state.items=read();persist();$('#modal').close();render();toast('내 루틴을 저장했어요. 다음 방문에도 유지됩니다.');};update();}
function buildPhases(){const phases=[{kind:'warmup',seconds:180}];state.items.forEach(x=>{phases.push({kind:'move',id:x.id,seconds:60});for(let n=1;n<=x.sets;n++){phases.push({kind:'work',id:x.id,set:n,sets:x.sets,seconds:60});if(n<x.sets)phases.push({kind:'rest',id:x.id,set:n,seconds:x.rest});}});phases.push({kind:'cooldown',seconds:budget().cool});return phases;}
function elapsed(){const s=state.session;return s?Math.min(2400,s.elapsed+(s.paused?0:Math.max(0,Date.now()-s.anchor)/1000)):0;}
function pos(){const s=state.session;const time=elapsed();let at=0;for(let i=0;i<s.phases.length;i++){const phase=s.phases[i];if(time<at+phase.seconds)return {phase,index:i,remaining:at+phase.seconds-time,elapsed:time};at+=phase.seconds;}return {phase:null,index:s.phases.length,remaining:0,elapsed:time};}
function title(p){return !p?'오늘의 운동 완료':p.kind==='warmup'?'가볍게 몸 풀기':p.kind==='cooldown'?'이제, 호흡을 정리해요':p.kind==='rest'?'잠깐, 쉬어가요':p.kind==='move'?`${machines[p.id].name} 준비`:machines[p.id].name;}
function instruction(p){return !p?'오늘도 수고하셨습니다.':p.kind==='warmup'?'편안하게 걷고, 오늘의 몸 상태를 확인해요.':p.kind==='cooldown'?'기구를 정리하고, 편안하게 숨을 고르세요.':p.kind==='rest'?`${p.seconds}초 휴식 · 다음 세트는 자동으로 알려드릴게요.`:p.kind==='move'?'사용한 기구 정리 → 다음 기구 이동 → 자세 준비':`${p.set} / ${p.sets}세트 · 가벼운 무게, 통제할 수 있는 움직임` ;}
function announce(p){if(!p)return '40분 운동을 마쳤습니다. 수고하셨습니다.';if(p.kind==='warmup')return '운동을 시작하겠습니다. 가볍게 몸을 풀어주세요.';if(p.kind==='cooldown')return '운동 기구를 정리하고 천천히 호흡을 가다듬으세요.';if(p.kind==='rest')return `세트가 끝났습니다. ${p.seconds}초 동안 쉬세요.`;if(p.kind==='move')return `사용한 기구를 정리하고 ${machines[p.id].name}를 준비하세요.`;return `${machines[p.id].name}, ${p.set}번째 세트를 시작하겠습니다.`;}
function addLog(text){logs.unshift({time:fmt(elapsed()),text});logs=logs.slice(0,12);const log=$('#cue-log');if(log)log.innerHTML=logs.map(x=>`<li>${x.time} &nbsp; ${x.text}</li>`).join('');}
function speech(text){if(!state.sound)return;if(!('speechSynthesis'in window)){toast('이 브라우저는 음성 합성을 지원하지 않아요. 안내 자막을 확인해주세요.');return;}speechSynthesis.cancel();const utterance=new SpeechSynthesisUtterance(text);utterance.lang='ko-KR';utterance.rate=.94;const voice=speechSynthesis.getVoices().find(v=>v.lang.startsWith('ko'));if(voice)utterance.voice=voice;utterance.onerror=e=>{if(!['interrupted','canceled'].includes(e.error))toast('한국어 음성을 재생하지 못했어요. 기기 음성과 브라우저 설정을 확인해주세요.');};speechSynthesis.speak(utterance);}
async function audioReady(){const Audio=window.AudioContext||window.webkitAudioContext;if(!Audio)return;ctx??=new Audio();if(ctx.state==='suspended')await ctx.resume();}
function beep(final=false){if(!state.sound||!ctx)return;const osc=ctx.createOscillator(),gain=ctx.createGain();osc.type='sine';osc.frequency.value=final?1046:784;gain.gain.setValueAtTime(0,ctx.currentTime);gain.gain.linearRampToValueAtTime(.12,ctx.currentTime+.01);gain.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+(final?.34:.15));osc.connect(gain);gain.connect(ctx.destination);osc.start();osc.stop(ctx.currentTime+(final?.38:.18));}
let testInterval;async function testBeeps(){await audioReady();clearInterval(testInterval);if(!state.sound){toast('안내음을 먼저 켜주세요.');return;}window.speechSynthesis?.cancel();let n=5;toast('5초 비프 시연 · 5');beep();testInterval=setInterval(()=>{n--;if(n>0){beep();toast(`5초 비프 시연 · ${n}`);}else{clearInterval(testInterval);beep(true);toast('종료 신호 · 실제 세트에서도 같은 방식으로 안내해요.');}},1000);}
async function start(){if(state.session)return;await audioReady();clearInterval(testInterval);state.session={id:String(Date.now()),phases:buildPhases(),anchor:Date.now(),elapsed:0,paused:false,confirmed:[],lastIndex:0,lastBeep:'',split:state.split,simulated:false};logs=[];persist();render();addLog(announce(state.session.phases[0]));speech(announce(state.session.phases[0]));window.scrollTo(0,0);}
function liveView(){const p=pos(),s=state.session;const next=s.phases.slice(p.index+1).find(x=>x.kind==='work');return heading('FOCUS SESSION / '+levelLabel().toUpperCase(),'지금은, 이 동작 하나만.','순서와 시간은 맡겨두세요. 호흡과 자세에 집중해요.')+`<div class="live-layout"><section class="main-column"><div class="focus-card"><div class="live-overline" id="live-status">${s.paused?'PAUSED · 일시정지':'GUIDED · 자동 진행'}</div><h2 id="live-title">${title(p.phase)}</h2><p id="live-instruction">${instruction(p.phase)}</p><div class="big-timer" id="timer" role="timer">${fmt(p.remaining)}</div><p id="countdown-label">다음 단계까지</p><div class="progress"><i id="total-progress" style="width:${p.elapsed/24}%"></i></div><div class="live-times"><span id="elapsed">전체 ${fmt(p.elapsed)}</span><span id="remaining">${fmt(2400-p.elapsed)} 남음</span></div></div><div class="live-buttons"><button class="primary" id="complete-set" ${p.phase?.kind!=='work'||s.paused?'disabled':''}>✓ 세트 완료</button><button class="secondary" id="pause">${s.paused?'▶ 다시 시작':'Ⅱ 일시정지'}</button></div><div id="live-coach">${p.phase?.id?`<div class="live-machine"><button data-detail="${p.phase.id}"><img src="assets/${p.phase.id}.svg" alt="${machines[p.phase.id].shape}"></button><div><h3>작은 코칭</h3><p>${machines[p.phase.id].cue}</p><button class="text-button" data-detail="${p.phase.id}">자세와 기구 보기 ↗</button></div></div>`:`<div class="reason"><span class="reason-icon">↻</span><p>쉬고 싶을 때는 일시정지를 누르세요.<br>통증이 있다면 언제든 운동을 중단할 수 있어요.</p></div>`}</div><div class="section-head"><h2>아직 시작하지 않은 운동</h2><span class="caption">붐비면 순서 교체</span></div><div id="upcoming">${upcomingView(p)}</div><button class="text-button" id="end-session" style="margin-top:20px">오늘은 여기까지 · 중간 종료</button></section><aside class="aside"><div class="card"><h3>귀로 듣는 진행 안내</h3><ul class="log" id="cue-log">${logs.map(x=>`<li>${x.time} &nbsp; ${x.text}</li>`).join('')}</ul>${next?`<div class="live-next"><img src="assets/${next.id}.svg" alt="${machines[next.id].name}"><div><p>다음 운동</p><strong>${machines[next.id].name}</strong></div></div>`:''}</div><div class="harness"><h3>INTERACTION LAB · 웹 하네스</h3><p>40분을 기다리지 않고 핵심 상황을 체험해요. 건너뛴 시간은 실제 운동 수행으로 처리하지 않습니다.</p><button class="secondary" id="jump-work">첫 운동 세트로 이동</button><button class="secondary" id="jump-five">세트 종료 5초 전 체험</button><button class="secondary" id="jump-finish">40분 완료 체험</button><p>잠금·백그라운드 음성 및 음악 덕킹은 웹 시연 범위 밖입니다.</p></div></aside></div>`;}
function upcomingView(p){const moves=state.session.phases.map((x,i)=>({...x,index:i})).filter(x=>x.kind==='move'&&x.index>p.index);return moves.length?moves.map((x,i)=>`<div class="live-next"><img src="assets/${x.id}.svg" alt="${machines[x.id].name}"><div style="flex:1"><strong>${machines[x.id].name}</strong><p>아직 시작하지 않은 운동</p></div>${i<moves.length-1?`<button class="secondary" style="font-size:10px;padding:9px" data-swap="${x.id}" data-with="${moves[i+1].id}">다음과 교체 ⇅</button>`:''}</div>`).join(''):'<p class="mini-note">남은 운동을 마치고 회복 구간으로 이어져요.</p>';}
function updateLive(){if(!state.session)return;let p=pos(),s=state.session;if(!p.phase){endSession(true);return;}if(!s.paused&&s.lastIndex!==p.index){const previous=s.phases[s.lastIndex];s.lastIndex=p.index;s.lastBeep='';if(previous?.kind==='work')beep(true);addLog(announce(p.phase));speech(announce(p.phase));persist();if(page==='today')render();return;}const remaining=Math.ceil(p.remaining);if(!s.paused&&p.phase.kind==='work'&&remaining<=5&&remaining>0&&s.lastBeep!==`${p.index}:${remaining}`){s.lastBeep=`${p.index}:${remaining}`;beep();addLog(`비프 · ${remaining}`);}if(page!=='today'||!$('#timer'))return;$('#timer').textContent=fmt(p.remaining);$('#elapsed').textContent=`전체 ${fmt(p.elapsed)}`;$('#remaining').textContent=`${fmt(2400-p.elapsed)} 남음`;$('#total-progress').style.width=`${p.elapsed/24}%`;$('#countdown-label').textContent=p.phase.kind==='work'&&remaining<=5?`${remaining} · 종료 준비`:'다음 단계까지';}
function pause(){const s=state.session;s.elapsed=elapsed();s.anchor=Date.now();s.paused=!s.paused;window.speechSynthesis?.cancel();persist();render();if(!s.paused)speech('운동을 다시 시작합니다.');}
function completeSet(){const p=pos(),s=state.session;if(s.paused||p.phase.kind!=='work')return;s.confirmed.push(p.index);s.phases[p.index].seconds-=p.remaining;s.phases.at(-1).seconds+=p.remaining;persist();updateLive();}
function jump(which){const s=state.session;let at=0,target=0;for(const p of s.phases){if(p.kind==='work'){target=at+(which==='five'?p.seconds-5:0);break;}at+=p.seconds;}if(which==='finish')target=2400;s.elapsed=target;s.anchor=Date.now();s.paused=false;s.lastIndex=-1;s.lastBeep='';s.simulated=true;persist();updateLive();}
function endSession(complete){const s=state.session;if(!s)return;const r={id:s.id,split:s.split,at:Date.now(),elapsed:elapsed(),confirmed:s.confirmed.length,complete,simulated:s.simulated,effort:null};state.history.push(r);state.session=null;persist();speech(complete?'40분 운동을 마쳤습니다. 수고하셨습니다.':'오늘의 운동을 기록했습니다. 수고하셨습니다.');page='history';render();modal(complete?'오늘도, 해냈어요.':'내 페이스로 잘 마무리했어요.',`<div style="text-align:center"><div class="eyebrow">SESSION SAVED · 프로토타입 기록</div><div style="font-size:54px;color:#5e784a;margin:18px 0">${fmt(r.elapsed)}</div><p>직접 완료한 세트 ${r.confirmed}개<br>${r.simulated?'하네스로 시간을 이동한 시연 기록입니다.':'시간 경과와 실제 운동 수행은 따로 기록합니다.'}</p><h3 style="margin-top:25px">오늘 운동은 어땠어요?</h3><div class="live-buttons"><button class="secondary" data-effort="easy">여유로웠어요</button><button class="secondary" data-effort="hard">버거웠어요</button></div><p class="mini-note">다음 루틴은 날짜만이 아니라 수행·피로 기록으로 조절하도록 설계합니다.</p></div>`);document.querySelectorAll('[data-effort]').forEach(b=>b.onclick=()=>{r.effort=b.dataset.effort;persist();$('#modal').close();render();});}
function bind(){document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{page=b.dataset.page;render();window.scrollTo(0,0);});document.querySelectorAll('[data-detail]').forEach(b=>b.onclick=()=>showDetail(b.dataset.detail));document.querySelectorAll('[data-level]').forEach(b=>b.onclick=()=>{state.level=b.dataset.level;persist();render();});document.querySelectorAll('[data-feeling]').forEach(b=>b.onclick=()=>{state.feeling=b.dataset.feeling;setItems();});document.querySelectorAll('[data-up],[data-down]').forEach(b=>b.onclick=()=>{const i=Number(b.dataset.up??b.dataset.down),j=i+(b.dataset.up!==undefined?-1:1);[state.items[i],state.items[j]]=[state.items[j],state.items[i]];persist();render();});document.querySelectorAll('[data-swap]').forEach(b=>b.onclick=()=>{const s=state.session,p=pos();const a=b.dataset.swap,c=b.dataset.with;const ia=s.phases.findIndex(x=>x.id===a),ic=s.phases.findIndex(x=>x.id===c);if(ia<=p.index||ic<=p.index)return;const starts=s.phases.map((x,i)=>x.kind==='move'?i:-1).filter(i=>i>=0);const blocks=starts.map((at,i)=>s.phases.slice(at,starts[i+1]??s.phases.length-1));const ai=blocks.findIndex(x=>x[0].id===a),ci=blocks.findIndex(x=>x[0].id===c);[blocks[ai],blocks[ci]]=[blocks[ci],blocks[ai]];s.phases=[s.phases[0],...blocks.flat(),s.phases.at(-1)];persist();render();});if($('#split'))$('#split').onchange=e=>{state.split=e.target.value;setItems();};if($('#starter'))$('#starter').onchange=e=>{state.starter=e.target.checked;setItems();};if($('#sound'))$('#sound').onchange=e=>{state.sound=e.target.checked;if(!state.sound){window.speechSynthesis?.cancel();clearInterval(testInterval);}persist();};if($('#customize'))$('#customize').onclick=customize;if($('#start'))$('#start').onclick=start;if($('#voice-test'))$('#voice-test').onclick=()=>{if(!state.sound)return toast('안내음을 먼저 켜주세요.');speech('운동을 시작하겠습니다. 오늘도 나에게 집중하는 40분, 함께해요.');};if($('#beep-test'))$('#beep-test').onclick=testBeeps;if($('#pause'))$('#pause').onclick=pause;if($('#complete-set'))$('#complete-set').onclick=completeSet;if($('#jump-work'))$('#jump-work').onclick=()=>jump('work');if($('#jump-five'))$('#jump-five').onclick=()=>jump('five');if($('#jump-finish'))$('#jump-finish').onclick=()=>jump('finish');if($('#end-session'))$('#end-session').onclick=()=>{modal('오늘은 여기까지 할까요?','<p>중간 종료로 기록하고 남은 안내를 멈춥니다.</p><button class="primary" id="confirm-end" style="margin-top:20px">중간 종료하고 기록</button>');$('#confirm-end').onclick=()=>{$('#modal').close();endSession(false);};};}
$('#close-modal').onclick=()=>$('#modal').close();$('#modal').addEventListener('close',()=>{clearInterval(demoTimer);$('#modal-content').innerHTML='';});$('.brand').onclick=e=>{e.preventDefault();page='today';render();};document.addEventListener('visibilitychange',()=>{if(document.hidden){window.speechSynthesis?.cancel();}else if(state.session){updateLive();}});setInterval(updateLive,100);render();if(saveError)toast('기존 저장 데이터를 읽지 못했어요. 원본 보호를 위해 새 저장을 중단했습니다.');
